    # --- Data scanning ---

    def refresh(self) -> None:
        """Scan the transcripts directory and populate the tree."""
        thread = threading.Thread(
            target=self._do_scan,
            daemon=True,
            name="meetings-scan",
        )
        thread.start()

    def _do_scan(self) -> None:
        """Background: scan meeting folders and load summarization state."""
        try:
            from meet_enrich.discovery import scan_meeting_folders
            from meet_enrich.config import TRANSCRIPTS_ROOT
            from meet_summarize.state import load_state
            from meet_summarize.config import (
                TRANSCRIPTS_ROOT as SUM_ROOT,
                STATE_FILENAME,
            )

            self._root.after(0, self._log, "Scanning...", "progress")

            folders = scan_meeting_folders(transcripts_root=TRANSCRIPTS_ROOT)
            sum_state = load_state(SUM_ROOT / STATE_FILENAME)

            self._root.after(0, self._populate_tree, folders, sum_state)
        except ImportError as exc:
            self._root.after(
                0,
                self._log,
                f"Import error: {exc}. Install meet-enrich and meet-summarize.",
                "error",
            )
        except Exception as exc:
            logger.exception("Transcripts scan failed")
            self._root.after(0, self._log, f"Scan error: {exc}", "error")

    def _populate_tree(self, folders: list[Any], sum_state: dict) -> None:
        """Populate the Treeview from MeetingFolder objects and summarize state."""
        self._tree.delete(*self._tree.get_children())
        self._folders_by_key.clear()

        completed = sum_state.get("completed", {})
        failed = sum_state.get("failed", {})

        # Sort by date descending (newest first)
        folders_sorted = sorted(folders, key=lambda f: f.date, reverse=True)

        for folder in folders_sorted:
            folder_key = f"{folder.date}/{folder.name}"
            self._folders_by_key[folder_key] = folder

            # All data from MeetingFolder public fields
            concluded_status = "\u2713" if folder.concluded else "-"

            # Sources from MeetingFolder.artifact_sources + filesystem flags
            sources: list[str] = []
            for kind in folder.artifact_sources:
                display = ARTIFACT_DISPLAY_NAMES.get(kind, kind)
                if display not in sources:
                    sources.append(display)
            # Add filesystem-detected sources not in artifact_sources
            if folder.has_closed_caption and "CC" not in sources:
                sources.append("CC")
            if folder.has_chat and "Chat" not in sources:
                sources.append("Chat")
            if folder.has_checkpoint_processed:
                sources.append("Checkpoints")

            # Summary status from meet-summarize state
            if folder_key in completed:
                sum_status = "\u2713"
                tag = "success"
            elif folder_key in failed:
                sum_status = "\u2717"
                tag = "failed"
            else:
                sum_status = "-"
                tag = "pending"

            self._tree.insert(
                "",
                tk.END,
                iid=folder_key,
                values=(
                    folder.date,
                    folder.meeting_title or folder.name,
                    concluded_status,
                    sum_status,
                    ", ".join(sources),
                ),
                tags=(tag,),
            )

        count = len(folders_sorted)
        self._log(f"{count} transcript{'s' if count != 1 else ''}", "info")

    # --- Context menu ---

    def _dismiss_context_menu(self) -> None:
        """Destroy context menu and cancel timer."""
        if self._menu_timer:
            self._root.after_cancel(self._menu_timer)
            self._menu_timer = None
        if self._context_menu:
            try:
                self._context_menu.unpost()
                self._context_menu.destroy()
            except tk.TclError:
                pass
            self._context_menu = None

    def _on_tree_right_click(self, event: Any) -> None:
        """Show context menu for the selected meeting."""
        self._dismiss_context_menu()

        item = self._tree.identify_row(event.y)
        if not item:
            return
        self._tree.selection_set(item)

        # Check summary status from tree values (column index 4 = summarized)
        values = self._tree.item(item, "values")
        has_summary = len(values) > 4 and values[4] == "\u2713"

        menu = tk.Menu(
            self._parent,
            tearoff=0,
            bg="#2a2a2a",
            fg="#ffffff",
            activebackground="#444444",
            activeforeground="#ffffff",
        )
        self._context_menu = menu

        def open_folder() -> None:
            self._dismiss_context_menu()
            self._open_meeting_folder(item)

        def view_summary() -> None:
            self._dismiss_context_menu()
            self._view_summary(item)

        menu.add_command(label="Open Folder", command=open_folder)
        if has_summary:
            menu.add_command(label="View Summary", command=view_summary)
        else:
            menu.add_command(label="View Summary", state=tk.DISABLED)

        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

        # Auto-dismiss after timeout (Linux can't dismiss on click-away)
        self._menu_timer = self._root.after(MENU_TIMEOUT, self._dismiss_context_menu)

    def _open_meeting_folder(self, folder_key: str) -> None:
        """Open the meeting folder in the file manager."""
        folder = self._folders_by_key.get(folder_key)
        if folder is None:
            return
        if folder.path.exists():
            subprocess.Popen(["xdg-open", str(folder.path)])

    def _view_summary(self, folder_key: str) -> None:
        """Show summary content in a popup.

        NOTE: Reading summary.md directly is a known boundary violation.
        Waiting on meet_summarize to expose get_summary(folder_path).
        """
        folder = self._folders_by_key.get(folder_key)
        if folder is None:
            return

        # TODO: Replace with meet_summarize.get_summary(folder.path)
        # when that API is available
        summary_path = folder.path / "summary.md"
        if not summary_path.exists():
            self._log(f"No summary for {folder_key}", "info")
            return

        try:
            content = summary_path.read_text()
        except OSError as exc:
            self._log(f"Error reading summary: {exc}", "error")
            return

        popup = tk.Toplevel(self._root)
        popup.title(f"Summary — {folder_key}")
        popup.configure(bg=BG_WINDOW)
        popup.geometry("700x500")

        text = tk.Text(
            popup,
            bg=BG_OUTPUT,
            fg=FG_TEXT,
            font=FONT_BODY,
            wrap=tk.WORD,
            padx=PAD,
            pady=PAD,
            highlightthickness=0,
        )
        scrollbar = tk.Scrollbar(popup, command=text.yview)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        text.configure(yscrollcommand=scrollbar.set)
        text.pack(fill=tk.BOTH, expand=True)
        text.insert("1.0", content)
        text.configure(state=tk.DISABLED)

        popup.bind("<Escape>", lambda _: popup.destroy())

    # --- Find Meetings (broad enrichment sweep) ---

    def _on_find_meetings(self) -> None:
        """Run meet-enrich with no date constraint to discover all meetings."""
        if self._running:
            return
        self._set_running(True)
        self._enrich_running = True
        self._log("Finding meetings...", "progress")

        thread = threading.Thread(
            target=self._do_find_meetings,
            daemon=True,
            name="meetings-find",
        )
        thread.start()

    def _do_find_meetings(self) -> None:
        """Background: run meet-enrich broad sweep."""
        try:
            from meet_enrich.enricher import run_enrichment

            def on_progress(phase: str, detail: str, ctx: dict[str, Any]) -> None:
                if phase == "processing":
                    current = ctx.get("current", 0)
                    total = ctx.get("total", 0)
                    msg = f"Processing {detail} ({current}/{total})"
                elif phase == "complete":
                    msg = "Find meetings complete"
                elif phase == "downloading":
                    msg = f"Downloading {detail}"
                elif phase == "discovery":
                    if detail == "complete":
                        msg = f"Discovered {ctx.get('count', 0)} meetings"
                    else:
                        msg = "Discovering meetings..."
                elif phase == "scanning":
                    msg = "Scanning folders..."
                else:
                    msg = f"{phase}: {detail}"
                self._event_queue.put(("enrich_progress", msg))

            summary = run_enrichment(on_progress=on_progress)
            self._event_queue.put(("enrich_done", summary))
        except Exception as exc:
            logger.exception("Find meetings failed")
            self._event_queue.put(("enrich_error", str(exc)))
        finally:
            self._enrich_running = False

    # --- Summarize (find and summarize anything that needs a summary) ---

    def _on_summarize_all(self) -> None:
        """Run meet-summarize to summarize all actionable meetings."""
        if self._running:
            return
        self._set_running(True, show_controls=True)
        self._summarize_running = True
        self._log("Finding meetings to summarize...", "progress")

        thread = threading.Thread(
            target=self._do_summarize_all,
            daemon=True,
            name="meetings-summarize",
        )
        thread.start()

    def _do_summarize_all(self) -> None:
        """Background: scan for actionable meetings and summarize them."""
        try:
            from meet_summarize.scanner import scan_meetings, filter_actionable
            from meet_summarize.executor import (
                run_batch,
                BatchConfig,
                ConcurrencyControl,
            )
            from meet_summarize.state import load_state
            from meet_summarize.config import TRANSCRIPTS_ROOT, STATE_FILENAME

            state_path = TRANSCRIPTS_ROOT / STATE_FILENAME
            state = load_state(state_path)
            candidates = scan_meetings(TRANSCRIPTS_ROOT)
            actionable = filter_actionable(candidates, state)

            if not actionable:
                self._event_queue.put(
                    ("summarize_progress", "No meetings need summarization")
                )
                self._event_queue.put(("summarize_done", (0, 0)))
                return

            count = len(actionable)
            self._event_queue.put(
                (
                    "summarize_progress",
                    f"Found {count} meeting{'s' if count != 1 else ''} to summarize",
                )
            )

            max_c = int(self._concurrency_var.get())
            self._cc = ConcurrencyControl(max_c)

            def on_event(event: Any) -> None:
                self._event_queue.put(("summarize_event", event))

            config = BatchConfig(
                max_concurrent=max_c,
                on_event=on_event,
                concurrency_control=self._cc,
            )

            success, failure = run_batch(actionable, state, state_path, config=config)
            self._event_queue.put(("summarize_done", (success, failure)))
        except Exception as exc:
            logger.exception("Summarization failed")
            self._event_queue.put(("summarize_error", str(exc)))
        finally:
            self._summarize_running = False
            self._cc = None

    # --- Controls ---

    def _on_pause(self) -> None:
        """Toggle pause/resume."""
        if self._cc is None:
            return
        if self._cc.is_paused:
            self._cc.resume()
            self._pause_btn.configure(text="Pause")
            self._log("Resumed", "info")
        else:
            self._cc.pause()
            self._pause_btn.configure(text="Resume")
            self._log("Paused", "info")

    def _on_stop(self) -> None:
        """Stop all running operations."""
        if self._cc is not None:
            self._cc.stop()
        self._log("Stopped", "error")
        self._set_running(False)

    def _on_concurrency_changed(self) -> None:
        """Update concurrency control when spinbox changes."""
        if self._cc is not None:
            try:
                self._cc.max_concurrent = int(self._concurrency_var.get())
            except (ValueError, AttributeError):
                pass

    def _set_running(self, running: bool, show_controls: bool = False) -> None:
        """Update button states for running/idle.

        Args:
            running: Whether a background operation is running.
            show_controls: Whether to show concurrency controls (stop/pause/agents).
        """
        self._running = running
        if running:
            self._find_btn.configure(state=tk.DISABLED)
            self._summarize_btn.configure(state=tk.DISABLED)
            if show_controls:
                self._concurrency_frame.pack(side=tk.LEFT)
            self._start_polling()
        else:
            self._find_btn.configure(state=tk.NORMAL)
            self._summarize_btn.configure(state=tk.NORMAL)
            self._concurrency_frame.pack_forget()
            self._pause_btn.configure(text="Pause")
            self._enrich_running = False
            self._summarize_running = False
            self._cc = None

    # --- Event polling ---

    def _start_polling(self) -> None:
        """Start polling the event queue."""
        if self._poll_id is not None:
            return
        self._poll_events()

    def _poll_events(self) -> None:
        """Process events from the queue."""
        had_events = False
        try:
            while True:
                event_type, data = self._event_queue.get_nowait()
                self._handle_event(event_type, data)
                had_events = True
        except Empty:
            pass

        # Keep polling if running OR if events were just processed (more may arrive)
        if (
            self._running
            or self._enrich_running
            or self._summarize_running
            or had_events
        ):
            self._poll_id = self._root.after(POLL_INTERVAL, self._poll_events)
        else:
            self._poll_id = None

    def _handle_event(self, event_type: str, data: Any) -> None:
        """Handle a single event from the queue."""
        if event_type == "enrich_progress":
            self._log(data, "progress")
        elif event_type == "enrich_done":
            summary = data
            files = summary.get("files_downloaded", 0)
            self._log(f"Enrichment complete: {files} files downloaded", "success")
            if not self._summarize_running:
                self._set_running(False)
                self.refresh()
        elif event_type == "enrich_error":
            self._log(f"Enrichment error: {data}", "error")
            if not self._summarize_running:
                self._set_running(False)
        elif event_type == "summarize_progress":
            self._log(data, "progress")
        elif event_type == "summarize_event":
            # meet-summarize passes events as single tuples: ("kind", ...)
            event_tuple = data
            kind = event_tuple[0] if event_tuple else ""
            if kind == "start":
                folder = event_tuple[1] if len(event_tuple) > 1 else ""
                self._log(f"Summarizing {folder}...", "progress")
                self._update_tree_tag(folder, "active")
            elif kind == "success":
                folder = event_tuple[1] if len(event_tuple) > 1 else ""
                self._log(f"\u2713 {folder}", "success")
                self._update_tree_tag(folder, "success")
                self._update_tree_value(folder, "summarized", "\u2713")
            elif kind == "failure":
                folder = event_tuple[1] if len(event_tuple) > 1 else ""
                self._log(f"\u2717 {folder}", "error")
                self._update_tree_tag(folder, "failed")
                self._update_tree_value(folder, "summarized", "\u2717")
            elif kind == "cancelled":
                folder = event_tuple[1] if len(event_tuple) > 1 else ""
                self._log(f"Cancelled {folder}", "info")
            elif kind == "total":
                count = event_tuple[1] if len(event_tuple) > 1 else 0
                self._log(f"Processing {count} meetings", "info")
            elif kind == "done":
                success = event_tuple[1] if len(event_tuple) > 1 else 0
                failure = event_tuple[2] if len(event_tuple) > 2 else 0
                self._log(
                    f"Summarization complete: {success} OK, {failure} failed",
                    "success",
                )
        elif event_type == "summarize_done":
            success, failure = data
            self._log(
                f"Done: {success} succeeded, {failure} failed",
                "success",
            )
            self._set_running(False)
            self.refresh()
        elif event_type == "summarize_error":
            self._log(f"Summarization error: {data}", "error")
            self._set_running(False)
        elif event_type == "pipeline_error":
            self._log(f"Error: {data}", "error")
            self._set_running(False)

    # --- Tree helpers ---

    def _update_tree_tag(self, folder_key: str, tag: str) -> None:
        """Update the tag (color) for a tree row."""
        if self._tree.exists(folder_key):
            self._tree.item(folder_key, tags=(tag,))

    def _update_tree_value(self, folder_key: str, column: str, value: str) -> None:
        """Update a single column value in the tree."""
        if not self._tree.exists(folder_key):
            return
        current = list(self._tree.item(folder_key, "values"))
        columns = ("date", "name", "concluded", "summarized", "sources")
        try:
            idx = columns.index(column)
            current[idx] = value
            self._tree.item(folder_key, values=current)
        except (ValueError, IndexError):
            pass

    # --- Logging ---

    def _log(self, message: str, tag: str = "info") -> None:
        """Append a message to the log area. Shows log frame on first message."""
        if not self._log_text or not self._log_text.winfo_exists():
            return

        # Show log frame on first log message
        if self._log_frame and not self._log_frame.winfo_ismapped():
            self._log_frame.pack(fill=tk.X, padx=PAD, pady=(PAD, PAD))

        timestamp = datetime.now().strftime("%H:%M:%S")
        self._log_text.configure(state=tk.NORMAL)
        self._log_text.insert(tk.END, f"[{timestamp}] ", "info")
        self._log_text.insert(tk.END, f"{message}\n", tag)
        self._log_text.see(tk.END)
        self._log_text.configure(state=tk.DISABLED)
